#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Sets up a Mac (Apple silicon) as the unattended build machine for the CEF
# builds: it never sleeps, starts again after a power cut, is reachable over
# SSH and Screen Sharing, and runs GitHub's Actions runner as a boot service
# for the user "builder", so nobody has to log in. Run it as an admin user,
# at the Mac or over Screen Sharing (some steps are in System Settings, the
# App Store and Disk Utility). Every stage checks what is already done, so it
# can be run again. See README.md, "Build machine".

TOTAL_STAGES=13

# Values kept for re-runs (no secrets): next to the admin's home, not in a repo.
ENV_FILE="$HOME/.magnetite-build-server.env"
REPO_SLUG="magnetite-browser/magnetite-cef"
RUNNER_LABEL="cef-builder"
BUILDER="builder"
BUILDER_HOME="/Users/$BUILDER"
RUNNER_HOME="$BUILDER_HOME/actions-runner"
DAEMON_LABEL="org.magnetitebrowser.actions-runner"
DAEMON_PLIST="/Library/LaunchDaemons/$DAEMON_LABEL.plist"
RUNNER_LOG="$BUILDER_HOME/Library/Logs/actions-runner.log"
COMPUTER_NAME="" SSH_PUBKEY="" RUNNER_TOKEN="" RUNNER_NAME="" WORK_DIR=""

[[ "$(uname -s)" == Darwin ]] || { echo "Run this on the Mac that should build (macOS)."; exit 1; }
[[ $EUID -ne 0 ]] || { echo "Run it as your admin user, without sudo; it asks for sudo itself."; exit 1; }
id -Gn | tr ' ' '\n' | grep -qx admin || { echo "Run it as a user with admin rights."; exit 1; }

banner "Magnetite build machine"

say "Your admin password, for the system settings this script changes:"
sudo -v

# ── 1 ────────────────────────────────────────────────────────────────────
stage "Check the machine"
ram_gb=$(($(sysctl -n hw.memsize) / 1073741824))
free_gb=$(df -g / | awk 'NR == 2 { print $4 }')
say "Chip:    $(sysctl -n machdep.cpu.brand_string)"
say "Memory:  ${ram_gb} GB"
say "macOS:   $(sw_vers -productVersion)"
say "Free on the internal disk: ${free_gb} GB"
[[ "$(uname -m)" == arm64 ]] || warn "Not an Apple silicon Mac: the builds expect one."
((ram_gb >= 16)) || warn "Under 16 GB of memory: a Chromium build will be very slow or fail."
((free_gb >= 250)) || note "Under 250 GB free here: plan an external SSD for the builds (stage 10)."
wired=$(networksetup -listallhardwareports | awk '/^Hardware Port: Ethernet$/ { getline; print $2; exit }')
if [[ -n "$wired" ]] && ipconfig getifaddr "$wired" >/dev/null 2>&1; then
  say "Network: cable ($wired, $(ipconfig getifaddr "$wired"))"
else
  warn "Not on a cable: a wired connection is steadier for a server and the large downloads."
fi
pause

# ── 2 ────────────────────────────────────────────────────────────────────
stage "Remote access: SSH and Screen Sharing"
say "With these on, the rest can be done from your desk."
open_url "x-apple.systempreferences:com.apple.Sharing-Settings.extension"
step "System Settings → General → Sharing."
step "Turn on Remote Login. Click (i): Allow access for: Only these users, just your admin user."
step "Leave 'Allow full disk access for remote users' off."
step "Turn on Screen Sharing. Click (i): Allow access for: Only these users, just your admin user."
step "Leave Remote Management off."
pause "Press Enter when both are on"
if nc -z -G 2 127.0.0.1 22 >/dev/null 2>&1; then say "✓ SSH answers"; else warn "SSH does not answer yet: check Remote Login."; fi
if nc -z -G 2 127.0.0.1 5900 >/dev/null 2>&1; then say "✓ Screen Sharing answers"; else warn "Screen Sharing does not answer yet."; fi
current=$(scutil --get LocalHostName 2>/dev/null || echo mac)
ask COMPUTER_NAME "Name on the network, letters, digits and dashes (Enter keeps '$current'):"
COMPUTER_NAME=${COMPUTER_NAME:-$current}
if [[ ! "$COMPUTER_NAME" =~ ^[A-Za-z0-9-]+$ ]]; then
  warn "'$COMPUTER_NAME' has other characters; keeping '$current'."
  COMPUTER_NAME=$current
fi
if [[ "$COMPUTER_NAME" != "$current" ]]; then
  sudo scutil --set ComputerName "$COMPUTER_NAME"
  sudo scutil --set LocalHostName "$COMPUTER_NAME"
  sudo scutil --set HostName "$COMPUTER_NAME"
fi
write_env COMPUTER_NAME "$COMPUTER_NAME"
say "From your laptop:  ssh $USER@$COMPUTER_NAME.local   ·   Screen Sharing: vnc://$COMPUTER_NAME.local"
note "Tip: give the Mac a fixed address in your router (DHCP reservation)."
pause

# ── 3 ────────────────────────────────────────────────────────────────────
stage "SSH key from your laptop (optional)"
say "With your key on this Mac, you log in from the laptop without the password."
step "On your laptop: cat ~/.ssh/id_ed25519.pub   (no key yet: ssh-keygen -t ed25519)"
note "That is the public half; never paste a private key anywhere."
ask SSH_PUBKEY "Paste the line that starts with ssh-ed25519 (Enter skips):"
if [[ -n "$SSH_PUBKEY" ]]; then
  if [[ "$SSH_PUBKEY" =~ ^(ssh-ed25519|ecdsa-sha2-nistp[0-9]+|sk-ssh-ed25519@openssh.com|ssh-rsa)\ [A-Za-z0-9+/=]+ ]]; then
    mkdir -p "$HOME/.ssh" && chmod 700 "$HOME/.ssh"
    touch "$HOME/.ssh/authorized_keys" && chmod 600 "$HOME/.ssh/authorized_keys"
    if grep -qxF "$SSH_PUBKEY" "$HOME/.ssh/authorized_keys"; then
      say "✓ the key was already there"
    else
      printf '%s\n' "$SSH_PUBKEY" >>"$HOME/.ssh/authorized_keys"
      say "✓ key added for $USER"
    fi
  else
    warn "That is not a public key line; nothing added."
  fi
fi
SSHD_DROPIN=/etc/ssh/sshd_config.d/050-magnetite.conf
if [[ -s "$HOME/.ssh/authorized_keys" && ! -f "$SSHD_DROPIN" ]]; then
  say "With a key in place, SSH can refuse passwords: then only your laptop's key gets in."
  step "On your laptop, check the key works:  ssh -o PasswordAuthentication=no $USER@$(scutil --get LocalHostName 2>/dev/null || echo mac).local true"
  if confirm "Did that log in without asking for a password? Then turn password login over SSH off"; then
    sudo tee "$SSHD_DROPIN" >/dev/null <<'SSHD'
# setup-mac.sh: keys only, admins only.
PasswordAuthentication no
KbdInteractiveAuthentication no
AllowGroups admin
SSHD
    # macOS starts sshd for each connection: the next login uses this.
    if sudo /usr/sbin/sshd -t; then
      say "✓ SSH takes keys only, for admins"
    else
      sudo rm -f "$SSHD_DROPIN"
      warn "sshd did not accept the setting; nothing changed."
    fi
  fi
fi
pause

# ── 4 ────────────────────────────────────────────────────────────────────
stage "Stay awake, come back after a power cut"
say "The Mac never sleeps (the display may), wakes for network access and starts by itself when power returns."
sudo pmset -a sleep 0 disksleep 0 displaysleep 10 womp 1 autorestart 1 powernap 0
sudo systemsetup -setrestartfreeze on >/dev/null 2>&1 ||
  note "Restart after a freeze is not set (that needs Full Disk Access for Terminal; optional)."
pmset -g | grep -E '^ *(sleep|disksleep|displaysleep|womp|autorestart) ' | sed 's/^ */  /' || true
pause

# ── 5 ────────────────────────────────────────────────────────────────────
stage "Firewall"
fw=/usr/libexec/ApplicationFirewall/socketfilterfw
sudo "$fw" --setglobalstate on >/dev/null
sudo "$fw" --setstealthmode on >/dev/null
say "$("$fw" --getglobalstate)"
say "$("$fw" --getstealthmode)"
note "SSH and Screen Sharing keep working; the runner only connects out to GitHub."
pause

# ── 6 ────────────────────────────────────────────────────────────────────
stage "Software updates"
say "Security fixes install by themselves. macOS and Xcode upgrades you start by hand:"
say "a new macOS or Xcode can change what the Chromium build needs."
open_url "x-apple.systempreferences:com.apple.Software-Update-Settings.extension"
step "System Settings → General → Software Update → (i) next to Automatic Updates:"
step "Check for updates: on · Download new updates when available: on"
step "Install macOS updates: off · Install application updates from the App Store: off"
step "Install Security Responses and system files: on"
pause

# ── 7 ────────────────────────────────────────────────────────────────────
stage "FileVault off, for an unattended start"
say "$(fdesetup status | head -1)"
if fdesetup status | grep -q "FileVault is On"; then
  say "With FileVault on, the Mac waits for a password after every power cut or crash."
  warn "Off means anyone who can reach this Mac can read and change its disk, builds included."
  if confirm "Turn FileVault off now?"; then
    sudo fdesetup disable
    note "Decryption carries on in the background; you can continue."
  else
    note "FileVault stays on: after a power cut, unlock it over SSH (macOS 26 or later)."
  fi
fi
note "No automatic login needed: the runner starts at boot as a system service."
pause

# ── 8 ────────────────────────────────────────────────────────────────────
stage "The builder user"
say "Builds run as '$BUILDER': a standard user without admin rights that never logs in."
if id "$BUILDER" >/dev/null 2>&1; then
  say "✓ '$BUILDER' exists"
else
  say "Choose a password for it when asked (it is not saved anywhere):"
  sudo sysadminctl -addUser "$BUILDER" -fullName "Magnetite builder" -password -
  sudo createhomedir -c -u "$BUILDER" >/dev/null
  # A service account: not offered on the login window.
  sudo dscl . create "/Users/$BUILDER" IsHidden 1
fi
# No login shell: the runner's launch daemon starts it directly.
sudo dscl . create "/Users/$BUILDER" UserShell /usr/bin/false
[[ -d "$BUILDER_HOME" ]] || sudo createhomedir -c -u "$BUILDER" >/dev/null
if id -Gn "$BUILDER" | tr ' ' '\n' | grep -qx admin; then
  warn "'$BUILDER' has admin rights; remove them in System Settings → Users & Groups."
fi
sudo -u "$BUILDER" mkdir -p "$BUILDER_HOME/Library/Logs"
pause

# ── 9 ────────────────────────────────────────────────────────────────────
stage "Xcode"
if [[ ! -d /Applications/Xcode.app ]]; then
  say "Chromium builds with Xcode itself, not only the Command Line Tools."
  open_url "macappstore://apps.apple.com/app/xcode/id497799835"
  step "Install Xcode from the App Store (sign in with an Apple Account if asked)."
  note "It is large; this can take a while."
  until [[ -d /Applications/Xcode.app ]]; do pause "Press Enter when Xcode is installed"; done
fi
sudo xcode-select -s /Applications/Xcode.app/Contents/Developer
sudo xcodebuild -license accept
sudo xcodebuild -runFirstLaunch >/dev/null
xcodebuild -version | sed 's/^/  /'
note "The build checks that this Xcode's macOS SDK is new enough for the Chromium it builds."
pause

# ── 10 ───────────────────────────────────────────────────────────────────
stage "Disk for the builds"
say "A Chromium checkout and build take about 250 GB. An external SSD (Thunderbolt or USB-C)"
say "keeps them off the system disk."
if confirm "Use an external SSD for the builds?"; then
  if [[ ! -d /Volumes/cef ]]; then
    warn "Erasing deletes everything on that SSD."
    step "Disk Utility → View → Show All Devices."
    step "Select the SSD itself (its top line, not a volume) → Erase."
    step "Name: cef · Format: APFS · Scheme: GUID Partition Map → Erase."
    open -a "Disk Utility"
    until [[ -d /Volumes/cef ]]; do pause "Press Enter when the volume 'cef' is there"; done
  fi
  WORK_DIR=/Volumes/cef/_work
  sudo diskutil enableOwnership /Volumes/cef >/dev/null
  sudo mkdir -p "$WORK_DIR"
  sudo chown "$BUILDER:staff" /Volumes/cef "$WORK_DIR"
  sudo mdutil -i off /Volumes/cef >/dev/null
  sudo tmutil addexclusion -p /Volumes/cef >/dev/null 2>&1 ||
    note "Not excluded from Time Machine (needs Full Disk Access for Terminal); do it in its settings if you back up this Mac."
  say "Free on the SSD: $(df -g /Volumes/cef | awk 'NR == 2 { print $4 }') GB"
else
  WORK_DIR="$RUNNER_HOME/_work"
  note "The builds use the internal disk."
fi
write_env RUNNER_WORK_DIR "$WORK_DIR"
pause

# ── 11 ───────────────────────────────────────────────────────────────────
stage "GitHub: the $REPO_SLUG repository"
say "The runner belongs to the repository that holds the CEF build."
open_url "https://github.com/$REPO_SLUG"
step "Page not found? Create it: github.com/new → Owner magnetite-browser, name magnetite-cef, Public."
pause "Press Enter when the repository exists"
open_url "https://github.com/$REPO_SLUG/settings/actions"
step "Settings → Actions → General:"
step "Approval for running fork pull request workflows from contributors:"
step "   Require approval for all external contributors."
step "Workflow permissions: read access to contents and packages (not read and write)."
note "Why: in a public repository, a stranger's pull request could otherwise run its own"
note "workflow on this Mac."
pause

# ── 12 ───────────────────────────────────────────────────────────────────
stage "The runner"
say "GitHub's Actions runner, as '$BUILDER', started at every boot before anyone logs in."
if [[ ! -x "$RUNNER_HOME/config.sh" ]]; then
  release=$(curl -fsSL https://api.github.com/repos/actions/runner/releases/latest)
  read -r version sha < <(printf '%s' "$release" | /usr/bin/python3 -c '
import json, re, sys
r = json.load(sys.stdin)
m = re.search(r"<!-- BEGIN SHA osx-arm64 -->([0-9a-f]{64})<!-- END SHA osx-arm64 -->", r["body"])
print(r["tag_name"], m.group(1) if m else "")')
  [[ -n "$sha" ]] || { warn "No checksum for the macOS arm64 runner in release $version; stopping."; exit 1; }
  tarball="actions-runner-osx-arm64-${version#v}.tar.gz"
  # Under /tmp: builder unpacks it, and the admin's own temp folder is
  # closed to other users.
  download=$(mktemp -d /tmp/magnetite-runner.XXXXXX)
  curl -fsSL -o "$download/$tarball" "https://github.com/actions/runner/releases/download/$version/$tarball"
  if ! printf '%s  %s\n' "$sha" "$download/$tarball" | shasum -a 256 -c - >/dev/null; then
    warn "The download does not match its published checksum; nothing installed."
    exit 1
  fi
  chmod 755 "$download" && chmod 644 "$download/$tarball"
  sudo -u "$BUILDER" mkdir -p "$RUNNER_HOME"
  sudo -u "$BUILDER" tar xzf "$download/$tarball" -C "$RUNNER_HOME"
  rm -rf "$download"
  say "✓ runner $version installed (checksum verified)"
fi
if [[ ! -f "$RUNNER_HOME/.runner" ]]; then
  open_url "https://github.com/$REPO_SLUG/settings/actions/runners/new?arch=arm64&os=osx"
  step "Under 'Configure', copy only the token: the text after --token."
  note "It is valid for one hour and only registers runners. Paste it here, nowhere else."
  ask_secret RUNNER_TOKEN "Token:"
  ask RUNNER_NAME "Runner name (Enter for '$COMPUTER_NAME'):"
  RUNNER_NAME=${RUNNER_NAME:-$COMPUTER_NAME}
  # The token goes in through the environment, which the runner reads and
  # masks: on the command line, sudo would log it and `ps` would show it.
  export ACTIONS_RUNNER_INPUT_TOKEN="$RUNNER_TOKEN"
  (cd "$RUNNER_HOME" && sudo --preserve-env=ACTIONS_RUNNER_INPUT_TOKEN -u "$BUILDER" -H \
    ./config.sh --unattended --url "https://github.com/$REPO_SLUG" \
    --name "$RUNNER_NAME" --labels "$RUNNER_LABEL" --work "$WORK_DIR" --replace)
  unset ACTIONS_RUNNER_INPUT_TOKEN
  RUNNER_TOKEN=""
  write_env RUNNER_NAME "$RUNNER_NAME"
fi
# A launch daemon, not GitHub's launch agent: it runs at boot without a login.
sudo tee "$DAEMON_PLIST" >/dev/null <<PLIST
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
  <key>Label</key><string>$DAEMON_LABEL</string>
  <key>UserName</key><string>$BUILDER</string>
  <key>GroupName</key><string>staff</string>
  <key>WorkingDirectory</key><string>$RUNNER_HOME</string>
  <key>ProgramArguments</key><array><string>$RUNNER_HOME/run.sh</string></array>
  <key>EnvironmentVariables</key>
  <dict>
    <key>HOME</key><string>$BUILDER_HOME</string>
    <key>USER</key><string>$BUILDER</string>
    <key>LANG</key><string>en_US.UTF-8</string>
    <key>PATH</key><string>/usr/bin:/bin:/usr/sbin:/sbin:/usr/local/bin</string>
  </dict>
  <key>RunAtLoad</key><true/>
  <key>KeepAlive</key><true/>
  <key>ThrottleInterval</key><integer>30</integer>
  <key>StandardOutPath</key><string>$RUNNER_LOG</string>
  <key>StandardErrorPath</key><string>$RUNNER_LOG</string>
</dict>
</plist>
PLIST
sudo chown root:wheel "$DAEMON_PLIST" && sudo chmod 644 "$DAEMON_PLIST"
sudo launchctl bootout "system/$DAEMON_LABEL" >/dev/null 2>&1 || true
sudo launchctl bootstrap system "$DAEMON_PLIST"
say "Service $(sudo launchctl print "system/$DAEMON_LABEL" | grep -m1 -E '^[[:space:]]+state = ' | sed 's/^[[:space:]]*//' || true)"
open_url "https://github.com/$REPO_SLUG/settings/actions/runners"
step "The runner shows as Idle within a minute. Log: $RUNNER_LOG"
pause

# ── 13 ───────────────────────────────────────────────────────────────────
stage "Test: restart"
say "Last check: after a restart everything comes back without anyone logging in."
step "After the restart, from your laptop: ssh $USER@$COMPUTER_NAME.local"
step "The runner shows Idle again: https://github.com/$REPO_SLUG/settings/actions/runners"
if confirm "Restart now?"; then
  finish
  sudo shutdown -r now
  exit 0
fi

finish
